//@ run-pass
// stack_basic.sio — Tests for Stack64 fixed-capacity stack
// All definitions inlined (tests cannot import stdlib).
//
// T1: new stack is empty
// T2: push 3 items, size=3
// T3: pop returns last pushed value
// T4: peek doesn't change size
// T5: pop on empty returns -1

// ============================================================================
// Inlined definitions
// ============================================================================

struct Stack64 { data: [i64; 64], top: i64 }

fn stack_new() -> Stack64 with Mut {
    Stack64 { data: [0; 64], top: 0 }
}

fn stack_push(s: &! Stack64, val: i64) -> bool with Mut {
    if s.top >= 64 { return false }
    s.data[s.top as usize] = val
    s.top = s.top + 1
    true
}

fn stack_pop(s: &! Stack64) -> i64 with Mut {
    if s.top <= 0 { return 0 - 1 }
    s.top = s.top - 1
    s.data[s.top as usize]
}

fn stack_peek(s: &Stack64) -> i64 {
    if s.top <= 0 { return 0 - 1 }
    s.data[(s.top - 1) as usize]
}

fn stack_empty(s: &Stack64) -> bool { s.top == 0 }

fn stack_size(s: &Stack64) -> i64 { s.top }

// ============================================================================
// Tests
// ============================================================================

fn main() -> i32 with IO, Mut, Panic {
    var passed: i32 = 0
    var failed: i32 = 0

    // T1: new stack is empty
    let s1 = stack_new()
    if stack_empty(&s1) { passed = passed + 1 } else { failed = failed + 1; println("FAIL T1") }

    // T2: push 3 items, size=3
    var s2 = stack_new()
    let _ = stack_push(&! s2, 10)
    let _ = stack_push(&! s2, 20)
    let _ = stack_push(&! s2, 30)
    if stack_size(&s2) == 3 { passed = passed + 1 } else { failed = failed + 1; println("FAIL T2") }

    // T3: pop returns last pushed value
    var s3 = stack_new()
    let _ = stack_push(&! s3, 100)
    let _ = stack_push(&! s3, 200)
    let _ = stack_push(&! s3, 300)
    let v3 = stack_pop(&! s3)
    if v3 == 300 { passed = passed + 1 } else { failed = failed + 1; println("FAIL T3") }

    // T4: peek doesn't change size
    var s4 = stack_new()
    let _ = stack_push(&! s4, 42)
    let _ = stack_push(&! s4, 99)
    let peeked = stack_peek(&s4)
    let sz4 = stack_size(&s4)
    if peeked == 99 && sz4 == 2 { passed = passed + 1 } else { failed = failed + 1; println("FAIL T4") }

    // T5: pop on empty returns -1
    var s5 = stack_new()
    let v5 = stack_pop(&! s5)
    if v5 == 0 - 1 { passed = passed + 1 } else { failed = failed + 1; println("FAIL T5") }

    if failed == 0 {
        println("ALL 5 TESTS PASSED")
        return 0
    }
    return 1
}

//@ run-pass
// Symbolic Differentiation Test Suite
//
// Tests arena-based expression trees with symbolic differentiation,
// evaluation, simplification, and comparison against numerical derivatives.
//
// Self-contained: all functions inlined (tests cannot import).
//
// References:
//   Griewank & Walther, "Evaluating Derivatives" (2nd ed., SIAM, 2008)

// ============================================================================
// MATH HELPERS
// ============================================================================

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    abs_f64(a - b) < tol
}

fn floor_f64(x: f64) -> f64 with Mut, Panic, Div {
    let i = x as i32
    let f = i as f64
    if x < 0.0 && f != x { return f - 1.0 }
    return f
}

fn sin_f64(x: f64) -> f64 with Mut, Panic, Div {
    let pi = 3.141592653589793
    let two_pi = 6.283185307179586
    var t = x - floor_f64(x / two_pi) * two_pi
    if t > pi { t = t - two_pi }
    if t < 0.0 - pi { t = t + two_pi }
    var sum = t
    var term = t
    var n = 1
    while n <= 15 {
        term = 0.0 - term * t * t / (((2 * n) as f64) * ((2 * n + 1) as f64))
        sum = sum + term
        n = n + 1
    }
    return sum
}

fn cos_f64(x: f64) -> f64 with Mut, Panic, Div {
    return sin_f64(x + 1.5707963267948966)
}

fn exp_f64(x: f64) -> f64 with Mut, Panic, Div {
    let ln2 = 0.6931471805599453
    let k_f = floor_f64(x / ln2 + 0.5)
    let k = k_f as i32
    let r = x - k_f * ln2
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n <= 20 {
        term = term * r / (n as f64)
        sum = sum + term
        n = n + 1
    }
    var result = sum
    if k > 0 {
        var j = 0
        while j < k { result = result * 2.0; j = j + 1 }
    } else if k < 0 {
        var j = 0
        let neg_k = 0 - k
        while j < neg_k { result = result / 2.0; j = j + 1 }
    }
    return result
}

fn ln_f64(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 - 1000000.0 }
    var val = x
    var k = 0.0
    let e = 2.718281828459045
    while val > e {
        val = val / e
        k = k + 1.0
    }
    while val < 1.0 / e {
        val = val * e
        k = k - 1.0
    }
    let u = (val - 1.0) / (val + 1.0)
    let u2 = u * u
    var sum = u
    var term = u
    term = term * u2
    sum = sum + term / 3.0
    term = term * u2
    sum = sum + term / 5.0
    term = term * u2
    sum = sum + term / 7.0
    term = term * u2
    sum = sum + term / 9.0
    term = term * u2
    sum = sum + term / 11.0
    term = term * u2
    sum = sum + term / 13.0
    term = term * u2
    sum = sum + term / 15.0
    term = term * u2
    sum = sum + term / 17.0
    term = term * u2
    sum = sum + term / 19.0
    return 2.0 * sum + k
}

fn pow_f64(x: f64, n: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    return exp_f64(n * ln_f64(x))
}

// ============================================================================
// EXPRESSION ARENA
// ============================================================================

struct ExprArena {
    node_types: [i64; 64],
    values: [f64; 64],
    left: [i64; 64],
    right: [i64; 64],
    count: i64,
}

// Global arena — ExprResult { arena, idx } returns are zeroed by codegen
var SYMA: ExprArena = ExprArena {
    node_types: [0; 64],
    values: [0.0; 64],
    left: [-1; 64],
    right: [-1; 64],
    count: 0,
}

fn sym_reset() with Mut, Panic {
    SYMA = ExprArena {
        node_types: [0; 64],
        values: [0.0; 64],
        left: [-1; 64],
        right: [-1; 64],
        count: 0,
    }
}

// ============================================================================
